{"script": "import os

print("CWD:", os.getcwd())
print("--- root listing ---")
try:
    for e in sorted(os.listdir('.')):
        p = os.path.join('.', e)
        print(('DIR ' if os.path.isdir(p) else 'FILE'), e)
except Exception as ex:
    print("err:", ex)

for d in ('data', 'tools'):
    print(f"--- {d}/ ---")
    try:
        items = sorted(os.listdir(d))
        print(f"(共 {len(items)} 项)")
        for e in items[:60]:
            p = os.path.join(d, e)
            print(('DIR ' if os.path.isdir(p) else 'FILE'), e)
    except Exception as ex:
        print("err:", ex)
"}

